

# =====================================================================
# THE CELLS OF CHAPTER 29 — F1 the Moab recital (29:1-8), F2 the covenant and the oath (29:9-14), F3 the individual's curse (29:15-20), F4 the land's desolation (29:21-27), F5 the hidden and the revealed (29:28) — each ask a case; the verdicts DATA rows or PARAMETERS, never the ink's
# =====================================================================
D0 = "the counter's day (40, 11, 1), before the marker"
def the_moab_recital(case, data):
    """F1 — Deut 29:1-8 — ONE LINE moab_recital_declared (STATUTE) writing covenant_words_keeping_commanded (a STATUS); the recital a RETELLING of the tape's own story — the plagues, the manna, the garment and the foot, Sihon and Og (exodus_story, good_land, opening_speech, gad_reuben by CALL — reference rows, never a second act); 5:1's opening seven in order (covenant_at_horeb by CALL); 28:69's footer reopened (firstfruits_ebal_curses by CALL)"""
    del P_[:]
    ask = case['ask']
    if ask == 'you_have_seen_all_the_lord_did_in_egypt':
        ink('29:1-2', "'AND MOSES CALLED TO ALL ISRAEL and said to them: YOU HAVE SEEN ALL THAT THE LORD DID before your eyes in the land of Egypt, to Pharaoh and to all his servants and to all his land — the great trials which your eyes saw, the signs and those great wonders' — the recital's frame 5:1's %s in order (the twin diffed %d)" % (TWIN['29:1 vs 5:1'], TWIN['29:1 vs 5:1']))
        move("cold_run_exodus_story (CALL) — ES.plagues(ten) = %s (%s); cold_run_covenant_at_horeb (CALL) — CH.the_assembly_called(hear_learn_keep_do) read" % (ES_TEN['v'], ES_TEN['fx'][0]), "the signs and the wonders RETOLD — the tape's ten plague lines and the going out by kind (plague_struck THIRTEEN, brought_out the tape's): a retelling is a REFERENCE ROW, never a second act (THE RETELLING RULES); Onkelos 'the trials rendered miracles'; the two assemblies — 5:1's and 29:1's")
        dat("THE LINE moab_recital_declared at %s, STATUTE by form; the readback rows 29:1-2 T1 REFERENCE rows against the tape's plague lines and brought_out" % D0)
        return out("you have seen all the LORD did in Egypt (29:1-2) — the recital's frame 5:1's call in order (%d shared); the signs and the wonders the tape's own %d plague lines and the going out, RETOLD as reference rows, never a second act: THE LINE moab_recital_declared at the counter's day" % (TWIN['29:1 vs 5:1'], ES_TEN['v']), ['accepted'])
    if ask == 'no_heart_to_know_until_this_day':
        ink('29:3', "'and the LORD has not given you a heart to know and eyes to see and ears to hear, UNTIL THIS DAY' — a saying on the forty years, no act; 'this day' the speaker's day, the counter's")
        move("the Sifrei 357 and the outside rows (the reading — 29:3 no row of its own); the shelf's reading (Avodah Zarah 5b — a man understands his teacher's mind only after forty years) OWED to the docket", "the heart to know given after forty years — a DATA note on the speaker's day; no write")
        dat("no write — the saying's seat; 'until this day' the counter's (40, 11, 1); the readback row 29:3 VARIANT against the tape's forty years")
        return out("no heart to know until this day (29:3) — a saying on the forty years at the speaker's day, no act and no write; the heart given after forty years the shelf's reading, owed to the docket", ['accepted'])
    if ask == 'forty_years_garments_and_sandals_not_worn':
        ink('29:4', "'and I led you FORTY YEARS in the wilderness; your garments did not wear out upon you and your sandal did not wear out upon your foot' — the parser's [40] at 29:4 (%s); 8:4's STATE told again in the plural (the twin diffed %d)" % (PARSE[(29, 4)][0], TWIN['29:4 vs 8:4']))
        move("cold_run_good_land (CALL) — GL.the_way_of_forty_years(the_garment_and_the_foot) = %s; GL.DATA the_garment_and_the_foot read; cold_run_opening_speech (CALL) — OS.the_bypass(forty_years_lacking_nothing) = %s" % (GL_GARMENT[0][:60], OS_40[0][:50]), "A STATE OVER FORTY YEARS told at 8:4 and here — NO LINE on the tape, NO ENTRY on any ledger (the kin's SUPPLIED row): the readback row REFERENCES the kin's row, no write of ours; 2:7's forty years lacking nothing the manna's (Exodus 16:35)")
        dat("no write — the state the kin's (good_land's SUPPLIED row on 8:4); the readback row 29:4 REFERENCE against the kin's cell; the parser's [40] the reading's own")
        return out("forty years, the garments and the sandals not worn (29:4) — 8:4's state told again in the plural (%d shared): the kin's SUPPLIED row referenced (good_land — %s), no line and no write; the parser's [40]" % (TWIN['29:4 vs 8:4'], GL_GARMENT[0][:40]), ['accepted'])
    if ask == 'sihon_and_og_smitten_and_their_land_given':
        ink('29:5-7', "'bread you did not eat and wine and strong drink you did not drink, that you may know that I am the LORD your God; and you came to this place, and SIHON king of Heshbon and OG king of Bashan came out against us to battle and we smote them; and we took their land and gave it for an inheritance to the Reubenite, the Gadite and the half tribe of Manasseh' — the parser's half at 29:7 (%s); the manna as no bread" % (PARSE[(29, 7)][0],))
        move("cold_run_opening_speech (CALL) — OS.sihon_and_og(og_turned) = %s; OS.sihon_and_og(the_ban) read; cold_run_gad_reuben (CALL) — GR.the_acceptance_and_the_charge(the_commission) = %s" % (OS_OG[0][:50], GR_COMM[0][:60]), "2:26-3:17's retelling of Numbers 21 and 32 RETOLD A THIRD TIME — the tape's sihon_smitten_land_possessed, og_came_out_and_fear_not and the two and a half tribes' lines (kings_smitten on sihon and og, holding_given on the half tribe of Manasseh): the readback rows SHORTENED against 3:1-17; the manna's forty years (Exodus 16:35 — manna_fell the tape's) TURNED to 'no bread'; Onkelos 'wine new and old'")
        dat("no write — the retellings reference rows; the parser's half (and to the half tribe) the store's %%; the readback rows 29:5-7 TURNED and SHORTENED")
        return out("Sihon and Og smitten and their land given (29:5-7) — 2:26-3:17's retelling retold a third time (opening_speech — %s; gad_reuben — the dividers), the manna as no bread: reference rows on the tape's own lines, no second act" % (OS_OG[0][:30],), ['accepted'])
    if ask == 'keep_the_words_of_this_covenant':
        ink('29:8', "'and you shall KEEP THE WORDS OF THIS COVENANT and do them, that you may prosper in all you do' — the recital's one command; 'the words of this covenant' 28:69's footer phrase")
        move("cold_run_firstfruits_ebal_curses (CALL) — FE.DATA the_three_covenants = %s (covenant_words_in_moab_declared ONE UNMOVED — 28:69 the footer, 29:1 opens what it named); Onkelos 29:8 'that you may prosper'" % (FE_THREE['value'][1],), "THE WRITE covenant_words_keeping_commanded — a STATUS on israel_people at the counter's day (DM2); the three covenants of the Sifrei 104:8 the footer's row — Horeb, the plains of Moab, Gerizim and Ebal")
        dat("THE WRITE covenant_words_keeping_commanded, a STATUS on israel_people at %s; the readback row 29:8 SUPPLIED with the line's write" % D0)
        return out("keep the words of this covenant (29:8) — the recital's one command after the retelling; 28:69's footer phrase reopened (the three covenants — %s): THE WRITE covenant_words_keeping_commanded, a STATUS on Israel at the counter's day" % (FE_THREE['value'][1],), ['covenant_words_keeping_commanded'])
    return 'no verdict in span', [], list(P_)


def the_covenant_and_the_oath(case, data):
    """F2 — Deut 29:9-14 — ONE LINE covenant_oath_entered_declared (STATUTE) writing standing_before_the_lord_this_day, covenant_oath_sworn_this_day and covenant_with_those_not_here (STATUSES); entered_the_covenant REUSED at 29:11 (the fourth entry) and became_the_lords_people_this_day REUSED at 29:12 (the second); the kin by CALL (seven_nations — the oath by kind, 29:12's run citation; seducers — the pointer row's form; covenant_at_horeb — 5:3's DATA note; not_righteousness — the fathers' merit; firstfruits_ebal_curses — 27:9's people this day)"""
    del P_[:]
    ask = case['ask']
    if ask == 'standing_this_day_all_of_you_before_the_lord':
        ink('29:9', "'YOU STAND THIS DAY, ALL OF YOU, BEFORE THE LORD YOUR GOD: your heads, your tribes, your elders and your officers, every man of Israel' — the ranks; 'this day' the counter's")
        move("the Sifrei 48:9 and 345:2 (the reading's outside rows — all equal in the Torah: priests, Levites and Israelites not written, 'the congregation of Jacob'; an inheritance for the small, not of kings alone); Onkelos 29:9", "THE WRITE standing_before_the_lord_this_day — a STATUS on israel_people at the counter's day (DM2); the assembly's ranks the four classes' frame (29:10)")
        dat("THE WRITE standing_before_the_lord_this_day, a STATUS on israel_people at %s; THE LINE covenant_oath_entered_declared's first verse — the readback row 29:9 SUPPLIED" % D0)
        return out("you stand this day, all of you, before the LORD (29:9) — the ranks from the heads to every man of Israel; all equal in the Torah (the Sifrei 48:9, 345:2): THE WRITE standing_before_the_lord_this_day, a STATUS on Israel at the counter's day", ['standing_before_the_lord_this_day'])
    if ask == 'from_the_hewer_of_wood_to_the_drawer_of_water':
        ink('29:10', "'your children, your wives and your stranger who is in your camp, FROM THE HEWER OF YOUR WOOD TO THE DRAWER OF YOUR WATER' — THE FOUR CLASSES the hakhel's list at 31:12 reuses (the men, the women, the children and the stranger); Onkelos 'the gatherer and the filler'")
        move("this runner's own F11 (31:12 the second seat of the four classes — the first intra-runner reference of the walk); cold_run_festivals_judges (CALL) — FJ.DATA the_exempt_from_appearing = %d exempt (the pilgrimage's list against the hakhel's four)" % (len(FJ_EXEMPT['value']['exempt']),), "the four classes a PARAMETER (the_four_classes) — 31:12's assembly WIDER than 16:16's appearing (Chagigah 1:1's exempt come); Onkelos's gatherer and filler the hewer and the drawer")
        dat("no write of its own — the classes the line's frame; THE PARAMETER the_four_classes (29:10 with 31:12); the readback row 29:10 VARIANT")
        return out("from the hewer of wood to the drawer of water (29:10) — the four classes, the men, the women, the children and the stranger: the hakhel's list at 31:12 the second seat (a parameter — wider than the pilgrimage's %d exempt by CALL to festivals_judges); Onkelos the gatherer and the filler" % (len(FJ_EXEMPT['value']['exempt']),), ['accepted'])
    if ask == 'to_enter_the_covenant_and_the_oath':
        ink('29:11', "'that you may enter INTO THE COVENANT of the LORD your God AND INTO HIS OATH which the LORD your God cuts with you this day' — the oath's own word in Onkelos (momata at 29:11, 13, 18 alone in the book — the reading's crown)")
        move("cold_run_firstfruits_ebal_curses (CALL) — FE.DATA the_three_covenants = %s (28:69 'besides the covenant at Horeb' — the second covenant, at Moab); Exodus 24:8's blood thrown (covenant_blood_thrown the tape's — entered_the_covenant's three seats)" % (FE_THREE['value'],), "entered_the_covenant REUSED — the FOURTH entry on Israel (Exodus 24's three the first); THE WRITE covenant_oath_sworn_this_day — a STATUS, the oath's clause distinct from the covenant's (DM2)")
        dat("THE WRITE covenant_oath_sworn_this_day, a STATUS on israel_people; entered_the_covenant REUSED at 29:11 (3 -> 4 over the sitting); the readback row 29:11 REFERENCE against covenant_blood_thrown (Exodus 24:8)")
        return out("to enter the covenant and the oath (29:11) — the second covenant, at Moab (the three of the Sifrei 104:8); Onkelos's oath-word at 29:11, 13, 18 alone in the book: THE WRITE covenant_oath_sworn_this_day, a STATUS; entered_the_covenant REUSED, the fourth entry after Exodus 24's three", ['covenant_oath_sworn_this_day', 'entered_the_covenant'])
    if ask == 'established_this_day_as_his_people_as_he_swore':
        ink('29:12', "'that He may establish you this day for a people to Himself and He will be your God, AS HE SPOKE TO YOU AND AS HE SWORE TO YOUR FATHERS, to Abraham, to Isaac and to Jacob' — THE FIRST AS_WHEN POINTER; 'swore' the seven's homograph (%s), no numeral" % (SEVENS_HOMOGRAPHS[0],))
        move("cold_run_seven_nations (CALL) — SN.the_holy_people(the_oath) = %s; cold_run_seducers (CALL) — SE.the_whole_offering_the_heap_and_the_mercy(as_he_swore_to_your_fathers) = %s (13:18's pointer row the form); cold_run_not_righteousness (CALL) — NR.DATA the_merit_of_the_fathers read (9:5); cold_run_firstfruits_ebal_curses (CALL) — FE.the_people_this_day(this_day_you_have_become_a_people_to_the_lord) = %s" % (SN_OATH[0][:50], SE_SWORE[0][:50], FE_PEOPLE[0][:50]), "the oath lines by kind BEHIND on the tape — the pointer a RUN_CITATION reference (the census's demand filed from its print); became_the_lords_people_this_day REUSED — 27:9's the first, 29:12 the second (the establishing); the eleven Torah seats of 'to Abraham, to Isaac and to Jacob' (the reading's formula)")
        dat("became_the_lords_people_this_day REUSED at 29:12 (1 -> 2 over the sitting); THE POINTER Deut 29:12 AS_WHEN predicted RUN_CITATION reference; the readback row 29:12 REFERENCE against people_this_day_declared (27:9)")
        return out("established this day as His people, as He swore to the fathers (29:12) — the oath lines by kind behind on the tape (seven_nations — %s; the pointer a run citation in 13:18's form): became_the_lords_people_this_day REUSED, the second entry after 27:9's" % (SN_OATH[0][:30],), ['became_the_lords_people_this_day'])
    if ask == 'with_him_who_stands_here_and_him_who_is_not':
        ink('29:13-14', "'and not with you alone do I cut this covenant and this oath, but WITH HIM WHO STANDS HERE WITH US THIS DAY before the LORD our God AND WITH HIM WHO IS NOT HERE WITH US THIS DAY' — the covenant's second party unbounded in time; Onkelos 'him who is not here'")
        move("cold_run_covenant_at_horeb (CALL) — CH.the_assembly_called(not_with_our_fathers) = %s" % (CH_NOTF[0][:70],), "5:3's 'not with our fathers but with us' the kin's DATA note against 29:13-14 — no link of our own; THE WRITE covenant_with_those_not_here — a STATUS on Israel (DM2): the covenant with the generations to come, the hakhel (31:12-13) its renewal made a clock — the compile's crown")
        dat("THE WRITE covenant_with_those_not_here, a STATUS on israel_people at %s; the readback rows 29:13-14 REFERENCE against the Horeb assembly's 5:3 by CALL" % D0)
        return out("with him who stands here and with him who is not here (29:13-14) — the covenant with the absent, the generations to come (5:3's note by CALL — no link of our own): THE WRITE covenant_with_those_not_here, a STATUS on Israel; the hakhel its renewal made a clock", ['covenant_with_those_not_here'])
    return 'no verdict in span', [], list(P_)


def the_individuals_curse(case, data):
    """F3 — Deut 29:15-20 — ONE LINE hidden_idolater_curse_declared (STATUTE) writing heart_turning_to_other_gods_barred and stubborn_self_blessing_barred (BLOCKS) and hidden_idolater_unpardoned, curses_of_the_book_on_the_idolater, name_blotted_from_under_heaven and separated_for_evil_from_all_tribes (HEAVEN entries, conditional); the kin by CALL (seducers — the inciter in secret; obey_horeb — wood and stone, the jealous God; seven_nations — the name from under heaven; erection — the calf's blotting; firstfruits_ebal_curses — the curses of the book)"""
    del P_[:]
    ask = case['ask']
    if ask == 'lest_a_heart_turn_to_serve_the_nations_gods':
        ink('29:15-17', "'for you know how we dwelt in the land of Egypt and passed through the nations; and you saw their abominations and their idols, WOOD AND STONE, silver and gold; LEST THERE BE AMONG YOU a man or woman or family or tribe WHOSE HEART TURNS THIS DAY FROM THE LORD our God to go and serve the gods of those nations' — the one 'lest' of the three chapters (%s)" % ([(c, v) for c, v in SPAN if 'פן' in W(c, v) or 'ופן' in W(c, v)],))
        move("cold_run_seducers (CALL) — SE.the_inciter(the_inciters_kin) = %s (13:7's inciter in secret — the individual idolater's kin); cold_run_obey_horeb (CALL) — OH.the_exile_case(serve_wood_and_stone) = %s (4:28's wood and stone); other_gods_barred ONE UNMOVED (the second word's block — covenant_at_horeb by CALL)" % (SE_KIN[0][:50], OH_WOOD[0][:50]), "THE WRITE heart_turning_to_other_gods_barred — a BLOCK on Israel at the counter's day (DM2): the covenant's own guard on the HEART, distinct from the second word's on the deed")
        dat("THE WRITE heart_turning_to_other_gods_barred, a BLOCK on israel_people at %s; THE LINE hidden_idolater_curse_declared's first verse 29:15 — the readback row SUPPLIED; 29:16 REFERENCE against the exile case's wood and stone" % D0)
        return out("lest a heart turn to serve the nations' gods (29:15-17) — the individual idolater in the covenant's assembly, 13:7's inciter his kin (seducers — %s), 4:28's wood and stone the idols': THE WRITE heart_turning_to_other_gods_barred, a BLOCK on Israel — the guard on the heart" % (SE_KIN[0][:30],), ['heart_turning_to_other_gods_barred'])
    if ask == 'a_root_bearing_gall_and_wormwood':
        ink('29:17', "'lest there be among you A ROOT BEARING GALL AND WORMWOOD' — the phrase ONCE in the Bible (the reading's formula); Onkelos 'a man thinking sins or rebellion' two tokens more — the root is a MAN")
        move("Onkelos 29:17 (the reading's row — the root a man); 'gall' the store's 'poisonous plant' patched at the reading's tail", "a DATA note on the figure — the root the hidden idolater himself; no write of its own (the block written at the heart's clause)")
        dat("no write — the figure's seat; the readback row 29:17 SUPPLIED with the line's first block")
        return out("a root bearing gall and wormwood (29:17) — the phrase once in the Bible; Onkelos reads the root as a man who thinks sins: the figure of the hidden idolater, a DATA note beside the heart's block", ['accepted'])
    if ask == 'he_blesses_himself_in_his_heart_in_stubbornness':
        ink('29:18', "'and it shall be, when he hears the words of THIS OATH, that HE BLESSES HIMSELF IN HIS HEART saying: I shall have peace though I walk in the stubbornness of my heart — to add the watered to the thirsty' — the oath's word again (Onkelos momata); 'saying' the self-blesser's (%s)" % ([f'{c}:{v}' for c, v in SPAN if 'לאמר' in W(c, v)][0],))
        move("Onkelos 29:18 (the reading's row) — 'he thinks' for 'blesses himself'; THE WATERED AND THE THIRSTY the sins of inadvertence added to the deliberate; 'the stubbornness of the heart' Jeremiah's word (a Prophets seat cited, never read)", "THE WRITE stubborn_self_blessing_barred — a BLOCK on Israel (DM2): the heart's clause a second block — the self-assurance under the oath")
        dat("THE WRITE stubborn_self_blessing_barred, a BLOCK on israel_people at %s; the readback row 29:18 SUPPLIED" % D0)
        return out("he blesses himself in his heart in stubbornness (29:18) — the oath heard and shrugged off, the watered added to the thirsty (Onkelos: the inadvertent to the deliberate): THE WRITE stubborn_self_blessing_barred, a BLOCK on Israel", ['stubborn_self_blessing_barred'])
    if ask == 'the_lord_will_not_pardon_his_anger_smokes':
        ink('29:19', "'THE LORD WILL NOT BE WILLING TO PARDON HIM, for then the anger of the LORD and His jealousy shall SMOKE against that man' — 'smoke' the verb's one seat here; 'His jealousy' 4:24's and 5:9's")
        move("cold_run_obey_horeb (CALL) — OH.no_image(consuming_fire_jealous_god) = %s; cold_run_hear_o_israel (CALL) — HI.the_gift_and_the_warning(the_jealous_god) = %s" % (OH_JEAL[0][:50], HI_JEAL[0][:50]), "THE WRITE hidden_idolater_unpardoned — a conditional HEAVEN entry on Israel (DM2): the LORD's act on the hidden idolater, the state never firing on the tape (the world's later run the judge)")
        dat("THE WRITE hidden_idolater_unpardoned, a HEAVEN entry (conditional) on israel_people at %s; the readback row 29:19 SUPPLIED with the verse's four writes" % D0)
        return out("the LORD will not pardon, His anger smokes (29:19) — the jealous God of 4:24 and 5:9 against that man (obey_horeb — %s): THE WRITE hidden_idolater_unpardoned, a conditional HEAVEN entry on Israel" % (OH_JEAL[0][:30],), ['hidden_idolater_unpardoned'])
    if ask == 'the_curse_written_in_this_book_lies_on_him':
        ink('29:19', "'and ALL THE CURSE WRITTEN IN THIS BOOK SHALL LIE UPON HIM' — 'the curse' singular with 'written' feminine, the whole curse one; 'in this book' 28:58, 29:19, 29:26 (%s)" % (P('בספר', 'הזה', books=T),))
        move("cold_run_firstfruits_ebal_curses (CALL) — FE.DATA the_hearkening_state = the curse arm %s (curses_for_not_hearkening ONE UNMOVED — chapter 28's curses the reference)" % (FE_STATE['value']['the_curse_arm'],), "THE WRITE curses_of_the_book_on_the_idolater — a conditional HEAVEN entry (DM2): the individual receives the nation's curse")
        dat("THE WRITE curses_of_the_book_on_the_idolater, a HEAVEN entry (conditional) on israel_people at %s" % D0)
        return out("the curse written in this book lies on him (29:19) — chapter 28's curse arm (%s) on the individual, the whole curse one: THE WRITE curses_of_the_book_on_the_idolater, a conditional HEAVEN entry" % (FE_STATE['value']['the_curse_arm'],), ['curses_of_the_book_on_the_idolater'])
    if ask == 'blotted_out_and_separated_for_evil':
        ink('29:19-20', "'and THE LORD WILL BLOT OUT HIS NAME FROM UNDER HEAVEN; and THE LORD WILL SEPARATE HIM FOR EVIL FROM ALL THE TRIBES OF ISRAEL, according to all the curses of the covenant written in this book of the law' — the phrase's seats %s; 'this book of the law' 28:61, 29:20, 30:10, 31:26" % (SN_NAME['value']['the_phrase'],))
        move("cold_run_seven_nations (CALL) — SN.DATA the_name_from_under_heaven (7:24's and 9:14's phrase; Amalek's at Exodus 17:14); cold_run_erection (CALL) — ER.calf(three_books) = %s (Exodus 32:32-33's blotting from the book — blotted_from_the_book ONE UNMOVED); Onkelos 29:20 'the LORD sets him apart'" % (ER_BOOKS['v'],), "THE WRITES name_blotted_from_under_heaven and separated_for_evil_from_all_tribes — conditional HEAVEN entries (DM2): the individual cut from the tribes' body")
        dat("THE WRITES name_blotted_from_under_heaven and separated_for_evil_from_all_tribes, HEAVEN entries (conditional) on israel_people at %s; the readback row 29:20 SUPPLIED; 29:19 REFERENCE against the calf's blotting" % D0)
        return out("blotted out and separated for evil (29:19-20) — the name from under heaven (7:24's phrase, %d seats), the calf's three books by CALL to erection (%s), the individual cut from the tribes: THE WRITES name_blotted_from_under_heaven and separated_for_evil_from_all_tribes, conditional HEAVEN entries" % (len(SN_NAME['value']['the_phrase']), ER_BOOKS['v'][0]), ['name_blotted_from_under_heaven', 'separated_for_evil_from_all_tribes'])
    return 'no verdict in span', [], list(P_)


def the_lands_desolation(case, data):
    """F4 — Deut 29:21-27 — ONE LINE land_desolation_answer_declared (STATUTE) writing land_brimstone_salt_like_sodom, nations_question_answered_covenant_forsaken and uprooted_and_cast_into_another_land (HEAVEN entries, conditional); the kin by CALL (mamre — Sodom's overthrow; tochacha — the desolation and the scattering, the transfers never fired; obey_horeb — the host apportioned with 29:25 by the Sifrei 148:8, the exile; good_land — serve and bow; firstfruits_ebal_curses — the plagues and the scattering); the ketiv and the qere at Zeboiim a DATA row; 'like the overthrow' a comparative — the pointer FALSE"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_later_generation_and_the_foreigner_see_the_plagues':
        ink('29:21', "'and THE LATER GENERATION, your children who rise after you, AND THE FOREIGNER who comes from a far land, shall say, when they see THE PLAGUES of that land and its sicknesses which the LORD has laid upon it' — 'the later generation' 29:21 and Psalm 48:14 (the Writings' seat cited); the foreigner Onkelos 'the son of the peoples'")
